struct R3Key{std::wstring path;~R3Key(){if(!path.empty())RegDeleteKeyW(HKEY_CURRENT_USER,path.c_str());}};
HTREEITEM r3node(State& s,HWND tree,app::DoorEntryKind kind,unsigned target){
    auto& items=tree==s.navigation?s.doors.navigation_items:s.doors.tree_items;
    for(std::size_t i=0;i<items.size();++i){const auto n=items[i];if(!n.group&&n.entry.kind==kind&&n.entry.target==target)return n.handle;if(tree==s.navigation)door_navigation_expand(s,n.handle);else door_tree_expand(s,n.handle);}throw std::runtime_error("round3 node missing");
}
